import re, math, unicodedata
import pandas as pd

def money(x):
    s = str(x).lower().replace('đ', '').replace(' ', '')
    if s.endswith('tr'):
        return float(s[:-2].replace(',', '.')) * 1e6
    if s.endswith('k'):
        return float(s[:-1].replace('.', '').replace(',', '.')) * 1e3
    return float(s.replace('.', '').replace(',', ''))

def to_date(x):  # excel serial, dd/mm/yyyy or "d thg m yyyy"
    s = str(x).strip()
    if re.fullmatch(r'\d{5}(\.0+)?', s):
        return pd.Timestamp('1899-12-30') + pd.Timedelta(days=float(s))
    d, m, y = map(int, re.findall(r'\d+', s)[:3])
    return pd.Timestamp(y, m, d)

